//go:build embedstatic

// Package web owns the production Aether frontend assets.
package web

import (
	"embed"
	"io/fs"
)

// staticFS contains the Next.js static export generated by the frontend build.
//
// The export is deliberately embedded in the native binary so production serving
// does not depend on the source checkout or a runtime frontend installation.
//
//go:embed all:out
var staticFS embed.FS

// StaticFS returns the embedded Next.js frontend filesystem.
func StaticFS() fs.FS {
	sub, err := fs.Sub(staticFS, "out")
	if err != nil {
		return nil
	}
	return sub
}
